'use strict';
const builtInSounds=[{id:'sunrise',name:'Zonsopkomst'},{id:'classic',name:'Klassiek'},{id:'pulse',name:'Pulse'},{id:'chimes',name:'Klankspel'}];
let mediaDBPromise,currentAlarmAudio=null,currentAudioURL=null,audioStopTimer=null,audioPlaybackVersion=0;
function mediaDB(){if(!mediaDBPromise)mediaDBPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('vyro-media',1);req.onupgradeneeded=()=>req.result.createObjectStore('sounds');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return mediaDBPromise}
async function storeSound(id,file){const db=await mediaDB();return new Promise((resolve,reject)=>{const tx=db.transaction('sounds','readwrite');tx.objectStore('sounds').put(file,id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function getSound(id){const db=await mediaDB();return new Promise((resolve,reject)=>{const req=db.transaction('sounds').objectStore('sounds').get(id);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function soundName(id){return builtInSounds.find(x=>x.id===id)?.name||state.customSounds?.find(x=>x.id===id)?.name||'Zonsopkomst'}
function soundOptions(selected='sunrise'){return `<optgroup label="Standaardgeluiden">${builtInSounds.map(x=>`<option value="${x.id}" ${selected===x.id?'selected':''}>${x.name}</option>`).join('')}</optgroup>${state.customSounds?.length?`<optgroup label="Mijn ringtones">${state.customSounds.map(x=>`<option value="${esc(x.id)}" ${selected===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</optgroup>`:''}`}
function stopAlarmSound(){audioPlaybackVersion++;clearTimeout(audioStopTimer);if(currentAlarmAudio){currentAlarmAudio.pause();currentAlarmAudio.currentTime=0;currentAlarmAudio=null}if(currentAudioURL){URL.revokeObjectURL(currentAudioURL);currentAudioURL=null}}
async function playAlarmSound(id='sunrise',preview=false){stopAlarmSound();const requestVersion=audioPlaybackVersion;try{let url;if(builtInSounds.some(x=>x.id===id))url='assets/sounds/'+id+'.wav';else{const blob=await getSound(id);if(!blob){toast('Dit geluidsbestand ontbreekt. Kies je ringtone opnieuw.');url='assets/sounds/sunrise.wav'}else url=currentAudioURL=URL.createObjectURL(blob)}if(requestVersion!==audioPlaybackVersion)return false;const player=new Audio(url);currentAlarmAudio=player;player.loop=!preview;player.volume=.8;player.onerror=()=>{stopAlarmSound();toast('Dit geluidsformaat kan niet worden afgespeeld. Kies MP3, WAV of M4A.')};await player.play();if(preview)audioStopTimer=setTimeout(stopAlarmSound,8000);return true}catch{stopAlarmSound();toast('Tik op Voorbeeld om geluid in deze browser te activeren.');return false}}
function avatarMarkup(extra=''){return state.profilePhoto?`<span class="avatar profile-avatar ${extra}"><img src="${esc(state.profilePhoto)}" alt="Mijn profielfoto"></span>`:`<span class="avatar profile-avatar ${extra}">${esc(state.name[0]?.toUpperCase()||'V')}</span>`}
function pickFile(accept){return new Promise(resolve=>{const input=document.createElement('input');input.type='file';input.accept=accept;input.hidden=true;document.body.appendChild(input);input.onchange=()=>{const file=input.files?.[0]||null;input.remove();resolve(file)};input.oncancel=()=>{input.remove();resolve(null)};input.click()})}
async function uploadRingtone(){const file=await pickFile('audio/*,.mp3,.m4a,.wav,.ogg,.aac');if(!file)return;if(file.size>20*1024*1024){toast('Kies een geluid van maximaal 20 MB');return}if(!file.type.startsWith('audio/')&&!/\.(mp3|m4a|wav|ogg|aac)$/i.test(file.name)){toast('Kies een audiobestand, zoals MP3 of WAV');return}const id='custom-'+Date.now();try{await storeSound(id,file);state.customSounds=state.customSounds||[];state.customSounds.push({id,name:file.name.slice(0,80)});save();const select=$('#alarmSound');if(select){select.innerHTML=soundOptions(id);select.value=id}toast('Ringtone toegevoegd. Sla je wekker op om hem te gebruiken.')}catch{toast('Opslaan van de ringtone lukt niet. Controleer de opslagruimte van je browser.')}}
async function uploadProfilePhoto(){const file=await pickFile('image/*');if(!file)return;if(file.size>20*1024*1024){toast('Kies een foto van maximaal 20 MB');return}let url;try{url=URL.createObjectURL(file);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=canvas.height=384;const ctx=canvas.getContext('2d');const size=Math.min(img.naturalWidth,img.naturalHeight);ctx.drawImage(img,(img.naturalWidth-size)/2,(img.naturalHeight-size)/2,size,size,0,0,384,384);const data=canvas.toDataURL('image/jpeg',.88);const previous=state.profilePhoto;state.profilePhoto=data;try{save()}catch{state.profilePhoto=previous;throw Error()}const preview=$('#profilePhotoPreview');if(preview)preview.innerHTML=avatarMarkup('large');toast('Profielfoto opgeslagen')}catch{toast('Deze foto kon niet worden geopend. Kies een JPG, PNG of WebP.')}finally{if(url)URL.revokeObjectURL(url)}}
